<?php require_once '../config/auth.php';require_role('admin');$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$v=array_map('floatval',[$_POST['nilai_tugas'],$_POST['nilai_uts'],$_POST['nilai_uas']]);$akhir=round(array_sum($v)/3,2);$q=$pdo->prepare('UPDATE nilai SET nilai_tugas=?,nilai_uts=?,nilai_uas=?,nilai_akhir=? WHERE id_nilai=?');$q->execute([...$v,$akhir,(int)$_POST['id_nilai']]);flash('success','Nilai diperbarui.');redirect('nilai.php');}$rows=$pdo->query('SELECT n.*,s.nama_siswa,mp.nama_mapel,g.nama_guru FROM nilai n JOIN siswa s ON s.nis=n.nis JOIN mata_pelajaran mp ON mp.id_mapel=n.id_mapel JOIN guru g ON g.id_guru=n.id_guru ORDER BY n.id_nilai DESC')->fetchAll();$page_title='Nilai Siswa';require '../includes/header.php';require '../includes/sidebar.php';require '../includes/flash.php'; ?><h2>Nilai Siswa</h2><div class="card p-3 table-responsive"><table class="table"><thead><tr><th>Siswa</th><th>Mapel</th><th>Guru</th><th>Tugas</th><th>UTS</th><th>UAS</th><th>Akhir</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['nama_siswa']) ?></td><td><?= e($r['nama_mapel']) ?></td><td><?= e($r['nama_guru']) ?></td><?php foreach(['nilai_tugas','nilai_uts','nilai_uas','nilai_akhir'] as $c): ?><td><?= e($r[$c]) ?></td><?php endforeach; ?><td><button class="btn btn-sm btn-outline-primary" data-bs-toggle="modal" data-bs-target="#n<?= $r['id_nilai'] ?>">Edit</button><div class="modal fade" id="n<?= $r['id_nilai'] ?>"><div class="modal-dialog"><div class="modal-content"><form method="post"><?= csrf_field() ?><div class="modal-header"><h5>Edit nilai</h5></div><div class="modal-body"><input type="hidden" name="id_nilai" value="<?= $r['id_nilai'] ?>"><?php foreach(['nilai_tugas','nilai_uts','nilai_uas'] as $c): ?><label><?= strtoupper(str_replace('nilai_','',$c)) ?></label><input class="form-control mb-2" type="number" min="0" max="100" step="0.01" name="<?= $c ?>" value="<?= e($r[$c]) ?>" required><?php endforeach; ?></div><div class="modal-footer"><button class="btn btn-primary">Simpan</button></div></form></div></div></div></td></tr><?php endforeach; ?></tbody></table></div><?php require '../includes/footer.php';
